// ResutoStudio: websites, sections, domains, creative.
// Owner: Agent F (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { idempotencyKey, uuid } from './common';
import type { SocialLinks } from './social-links';

export const studioContractsVersion = 2 as const;

export const WEBSITE_TEMPLATES = ['olive', 'smash', 'minimal'] as const;
export type WebsiteTemplate = (typeof WEBSITE_TEMPLATES)[number];

export const SECTION_KINDS = [
  'hero', 'about', 'menu_highlights', 'gallery', 'reservations', 'ordering', 'location', 'hours', 'testimonials', 'contact', 'custom',
] as const;
export type SectionKind = (typeof SECTION_KINDS)[number];

const hex = z.string().regex(/^#[0-9a-fA-F]{6}$/, 'a colour like #173f36');

/** Copy in both site languages. Either may be empty; the site falls back to the other. */
export const studioText = (max: number) =>
  z.object({ en: z.string().trim().max(max).optional(), ar: z.string().trim().max(max).optional() }).strict();
export type LocalizedText = { en?: string; ar?: string };

export const websiteTheme = z.object({
  primaryColor: hex.optional(),
  accentColor: hex.optional(),
  backgroundColor: hex.optional(),
  logoMediaId: uuid.nullable().optional(),
  heroMediaId: uuid.nullable().optional(),
  font: z.enum(['manrope', 'editorial']).optional(),
  /** Short line under the restaurant name in the site header (legacy "Example restaurant" slot). */
  tagline: studioText(80).optional(),
}).strict();
export type WebsiteTheme = z.infer<typeof websiteTheme>;

export const websiteSeo = z.object({
  title: studioText(70).optional(),
  description: studioText(170).optional(),
  ogMediaId: uuid.nullable().optional(),
}).strict();
export type WebsiteSeo = z.infer<typeof websiteSeo>;

export const updateWebsite = z.object({
  template: z.enum(WEBSITE_TEMPLATES).optional(),
  theme: websiteTheme.optional(),
  seo: websiteSeo.optional(),
}).strict();
export type UpdateWebsite = z.infer<typeof updateWebsite>;

export const sectionContent = z.object({
  eyebrow: studioText(60).optional(),
  headline: studioText(140).optional(),
  body: studioText(2000).optional(),
  ctaLabel: studioText(40).optional(),
  mediaId: uuid.nullable().optional(),
  mediaIds: z.array(uuid).max(24).optional(),
  productIds: z.array(uuid).max(12).optional(),
  items: z.array(z.object({ title: studioText(120), body: studioText(600).optional() }).strict()).max(12).optional(),
}).strict();
export type SectionContent = z.infer<typeof sectionContent>;

export const createSection = z.object({
  kind: z.enum(SECTION_KINDS),
  content: sectionContent.default({}),
  isVisible: z.boolean().default(true),
}).strict();
export type CreateSection = z.infer<typeof createSection>;

export const updateSection = z.object({
  content: sectionContent.optional(),
  isVisible: z.boolean().optional(),
}).strict();
export type UpdateSection = z.infer<typeof updateSection>;

export const reorderSections = z.object({ ids: z.array(uuid).min(1).max(50) }).strict();

export const publishWebsite = z.object({ key: idempotencyKey, note: z.string().trim().max(200).optional() }).strict();

export const updateMedia = z.object({ alt: z.string().trim().max(200).nullable().optional(), altAr: z.string().trim().max(200).nullable().optional() }).strict();

// --- Custom domains ---------------------------------------------------------
export const domainHostname = z.string().trim().toLowerCase()
  .max(253)
  .regex(/^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/, 'a domain such as www.example.com');
export const addDomain = z.object({ hostname: domainHostname }).strict();

export const DOMAIN_STATUSES = ['pending_verification', 'verified', 'provisioning', 'active', 'failed', 'removed'] as const;
export type DomainStatus = (typeof DOMAIN_STATUSES)[number];

export interface DnsRecordInstruction {
  type: 'TXT' | 'CNAME' | 'A';
  name: string;
  value: string;
  purpose: 'ownership' | 'routing';
}

export interface CustomDomainView {
  id: string;
  hostname: string;
  status: DomainStatus;
  sslStatus: 'pending' | 'issued' | 'failed' | 'not_applicable';
  provider: 'vercel' | 'manual';
  providerReadiness: 'implemented_unverified' | 'manual';
  verificationRecord: DnsRecordInstruction;
  routingRecords: DnsRecordInstruction[];
  instructions: string[];
  lastCheckedAt: string | null;
  verifiedAt: string | null;
  lastError: string | null;
  createdAt: string;
}

// --- Creative ---------------------------------------------------------------
export const CREATIVE_KINDS = ['caption', 'post', 'menu_description', 'website_copy'] as const;
export const generateCreative = z.object({
  kind: z.enum(CREATIVE_KINDS),
  locale: z.enum(['en', 'ar']),
  brief: z.string().trim().min(3).max(600),
  productId: uuid.optional(),
  tone: z.enum(['warm', 'playful', 'premium', 'direct']).default('warm'),
  variants: z.number().int().min(1).max(3).default(2),
}).strict();
export type GenerateCreative = z.infer<typeof generateCreative>;

export const reviewCreative = z.object({ status: z.enum(['approved', 'rejected', 'used']) }).strict();

export interface CreativeAsset {
  id: string;
  kind: string;
  locale: 'en' | 'ar';
  prompt: string;
  output: { variants: Array<{ title?: string; text: string; hashtags?: string[] }>; fallbackReason?: string };
  provider: string;
  model: string | null;
  isFallback: boolean;
  status: 'draft' | 'approved' | 'rejected' | 'used';
  createdAt: string;
}

// --- Branch storefronts (audit VP-05) ----------------------------------------
/** URL segment under the restaurant site (/r/<org>/<slug>). Reserved words are route names of the site. */
export const storefrontSlug = z.string().regex(/^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$/, 'lowercase letters, digits and dashes (3–48)')
  .refine((s) => !['revalidate', 'order', 'reserve', 'menu', 'pay', 'admin', 'api'].includes(s), 'this name is reserved');

export const storefrontTheme = z.object({
  primaryColor: hex,
  accentColor: hex,
  inkColor: hex.optional(),
  paperColor: hex.optional(),
}).strict();

/** Copy for one menu category on the storefront ("Burgers that hit different."). */
export const storefrontSection = z.object({
  categoryId: uuid,
  eyebrow: studioText(40).optional(),
  title: studioText(80).optional(),
  body: studioText(200).optional(),
}).strict();

export const storefrontContent = z.object({
  headline: studioText(120).optional(),
  body: studioText(400).optional(),
  /** Caption on the hero photo ("Made for the messy bite."). */
  heroNote: studioText(80).optional(),
  /** Optional banner above the menu ("The Smash combo."); products pictured beside it (up to 3). */
  promo: z.object({
    title: studioText(80).optional(),
    body: studioText(160).optional(),
    ctaLabel: studioText(40).optional(),
    ctaCategoryId: uuid.nullable().optional(),
    productIds: z.array(uuid).max(3).optional(),
  }).strict().optional(),
  sections: z.array(storefrontSection).max(30).optional(),
}).strict();
export type StorefrontContent = z.infer<typeof storefrontContent>;

export const upsertStorefront = z.object({
  slug: storefrontSlug,
  brandName: z.string().trim().min(1).max(80),
  brandNameAr: z.string().trim().max(80).nullable().optional(),
  tagline: studioText(120).optional(),
  theme: storefrontTheme,
  logoMediaId: uuid.nullable().optional(),
  heroMediaId: uuid.nullable().optional(),
  content: storefrontContent.default({}),
  isPublished: z.boolean().default(false),
}).strict();
export type UpsertStorefront = z.infer<typeof upsertStorefront>;

export interface StorefrontView {
  branchId: string;
  slug: string;
  brandName: string;
  brandNameAr: string | null;
  tagline: LocalizedText;
  theme: z.infer<typeof storefrontTheme>;
  logoMediaId: string | null;
  heroMediaId: string | null;
  content: StorefrontContent;
  isPublished: boolean;
  updatedAt: string;
}

/** A published storefront as the restaurant site lists it. */
export interface PublicStorefrontLink {
  slug: string;
  branchId: string;
  branchCode: string;
  name: string;
  nameAr: string | null;
  tagline: LocalizedText;
  primaryColor: string;
  accentColor: string;
  logoUrl: string | null;
  heroUrl: string | null;
  /** Site-relative path: /r/<org slug>/<storefront slug>. */
  path: string;
}

/** `GET /v1/public/sites/:slug/storefronts/:storefront`: branding only; the menu comes from the branch's live web menu. */
export interface PublicStorefront {
  slug: string;
  org: { slug: string; name: string; nameAr: string | null; currency: string; demo: boolean;
    /** Links shown as icons in the storefront footer (21-ONB); only valid https links on each network's hosts. */
    socialLinks?: SocialLinks };
  branch: {
    id: string; code: string; name: string; nameAr: string | null; city: string | null;
    /** The branch's neighbourhood (delivery label), English and Arabic; null when the branch has none (PAR-02). */
    district: string | null; districtAr: string | null;
    acceptsPickup: boolean; acceptsDelivery: boolean; openingHours: unknown; timezone: string;
  };
  brand: { name: string; nameAr: string | null; tagline: LocalizedText; primaryColor: string; accentColor: string; inkColor: string; paperColor: string; logoUrl: string | null; heroUrl: string | null };
  content: StorefrontContent;
  links: { site: string; order: string; menu: string };
}

// --- Public site ------------------------------------------------------------
export interface PublicSiteSection {
  id: string;
  kind: SectionKind;
  content: SectionContent & { media?: { url: string; alt: string | null } | null; gallery?: Array<{ url: string; alt: string | null }> };
}

export interface PublicSite {
  slug: string;
  revision: number;
  publishedAt: string | null;
  preview: boolean;
  /** demo: the platform's example tenant (labelled "Example restaurant", illustrations disclosed). */
  org: {
    name: string; nameAr: string | null; currency: string; country: string; defaultLocale: 'en' | 'ar'; demo: boolean;
    /** Links shown as icons (21-ONB); only valid https links on each network's hosts. */
    socialLinks?: SocialLinks;
  };
  template: WebsiteTemplate;
  theme: { primaryColor: string; accentColor: string; backgroundColor: string; font: 'manrope' | 'editorial'; logoUrl: string | null; heroUrl: string | null; tagline: LocalizedText };
  seo: { title: LocalizedText; description: LocalizedText; ogImageUrl: string | null };
  sections: PublicSiteSection[];
  branches: Array<{
    id: string; code: string; name: string; nameAr: string | null; address: string | null; city: string | null; phone: string | null;
    latitude: number | null; longitude: number | null; openingHours: unknown;
    acceptsDineIn: boolean; acceptsPickup: boolean; acceptsDelivery: boolean; acceptsReservations: boolean;
  }>;
  menuHighlights: Array<{
    id: string; name: string; nameAr: string | null; description: string | null; descriptionAr: string | null;
    priceMinor: number; currency: string; imageUrl: string | null; dietary: string[];
    /** "url 320w, url 640w, ..." over the stored WebP copies (null without copies); the original's pixel size. */
    imageSrcSet?: string | null; imageWidth?: number | null; imageHeight?: number | null;
  }>;
  canonicalHost: string | null;
  links: { reserve: string; order: string; site: string };
  /** Published branch storefronts (a branch trading under its own brand), linked from the site. */
  storefronts: PublicStorefrontLink[];
}

// --- studio_basic: logo, colours, theme presets (21-ONB increment 2) --------------
/**
 * PUT /v1/o/:orgId/brand: the part of the site's look every plan may change (STUDIO_BASIC_FEATURES). Strict: hero
 * images, taglines, SEO, sections, fonts and templates outside a preset are Studio-only and refused here.
 * `presetId` applies a theme preset (its colours, font and template); colours sent with it override the preset's.
 * `presetId: null` keeps the colours and forgets the preset.
 */
export const updateBrand = z.object({
  presetId: z.string().regex(/^[a-z][a-z0-9_]{1,39}$/).nullable().optional(),
  primaryColor: hex.optional(),
  accentColor: hex.optional(),
  backgroundColor: hex.optional(),
  logoMediaId: uuid.nullable().optional(),
}).strict();
export type UpdateBrand = z.infer<typeof updateBrand>;

/** POST /v1/o/:orgId/brand/publish: publishes the restaurant site as a new revision (the Studio publish, idempotent). */
export const publishBrand = z.object({ key: idempotencyKey }).strict();

/** A theme preset: a complete website theme and storefront theme for one kind of restaurant. */
export interface ThemePreset {
  id: string;
  name: LocalizedText;
  description: LocalizedText;
  template: WebsiteTemplate;
  websiteTheme: { primaryColor: string; accentColor: string; backgroundColor: string; font: 'manrope' | 'editorial' };
  storefrontTheme: { primaryColor: string; accentColor: string; inkColor: string; paperColor: string };
}

/** GET/PUT /v1/o/:orgId/brand. `scope` says whether the restaurant has the full Studio or only studio_basic. */
export interface BrandView {
  presetId: string | null;
  template: WebsiteTemplate;
  theme: { primaryColor: string; accentColor: string; backgroundColor: string; font: 'manrope' | 'editorial'; logoMediaId: string | null };
  logoUrl: string | null;
  website: { status: 'draft' | 'published'; publishedRevision: number; publishedAt: string | null; hasUnpublishedChanges: boolean };
  links: { site: string; menu: string };
  scope: 'studio_basic' | 'studio';
}

export interface BrandPublishResult { revision: number; publishedAt: string; links: { site: string; menu: string } }
